package com.lmspilot.course.domain; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param;
public interface CourseRepository extends JpaRepository<CourseEntity,UUID> { boolean existsByCodeIgnoreCase(String code); @Query("select c from CourseEntity c where (cast(:query as string) is null or lower(c.code) like lower(concat('%',cast(:query as string),'%')) or lower(c.name) like lower(concat('%',cast(:query as string),'%'))) and (:status is null or c.status=:status) and (cast(:categoryId as string) is null or c.categoryId=:categoryId)") Page<CourseEntity> search(@Param("query") String query,@Param("status") CourseStatus status,@Param("categoryId") UUID categoryId,Pageable pageable); }
